package main

import (
	"encoding/json"

	mockserver "github.com/mock-server/mockserver-monorepo/mockserver-client-go/v9"
)

func main() {
	client := mockserver.New("localhost", <port>)

	var e mockserver.Expectation
	_ = json.Unmarshal([]byte(`{
  "httpRequest" : {
    "method" : "GET",
    "path" : "/plain"
  },
  "httpResponse" : {
    "statusCode" : 200,
    "reasonPhrase" : "OK",
    "body" : {
      "type" : "STRING",
      "string" : "no quote, backtick or hash",
      "rawBytes" : "bm8gcXVvdGUsIGJhY2t0aWNrIG9yIGhhc2g="
    }
  },
  "id" : "plain",
  "priority" : 0,
  "timeToLive" : {
    "unlimited" : true
  },
  "times" : {
    "unlimited" : true
  }
}`), &e)
	client.Upsert(e)
}

