use mockserver_client::{ClientBuilder, Expectation};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let client = ClientBuilder::new("localhost", <port>).build()?;

    client.upsert(&[serde_json::from_str::<Expectation>(r#"{
  "httpRequest" : {
    "method" : "GET",
    "path" : "/plain"
  },
  "httpResponse" : {
    "statusCode" : 200,
    "reasonPhrase" : "OK",
    "body" : {
      "type" : "STRING",
      "string" : "no quote, backtick or hash",
      "rawBytes" : "bm8gcXVvdGUsIGJhY2t0aWNrIG9yIGhhc2g="
    }
  },
  "id" : "plain",
  "priority" : 0,
  "timeToLive" : {
    "unlimited" : true
  },
  "times" : {
    "unlimited" : true
  }
}"#)?])?;

    Ok(())
}

